// Scoring ICP BTP premium sur 100 pts — critere principal = signal de CA 300-400k€+ (volume avis Google comme proxy)
// Ne garde que score >= 60. Secteur: BTP/energie/sante non digitalise (piscines, renovation, construction generale, pompes a chaleur)
// Note: ce scorer travaille sur les ENTREPRISES scrapees via Google Maps, pas directement sur des profils LinkedIn de dirigeants.
// L'identification du dirigeant LinkedIn reste une etape manuelle/separee (recherche par nom d'entreprise) — ce node ne fait que qualifier l'entreprise.

function scoreCompany(p) {
  let score = 0;
  const reviews = p.reviewsCount || 0;
  const rating = p.totalScore || 0;
  const hasWebsite = !!p.website;

  // Signal CA (0-70 pts) — proxy = volume d'avis Google, calibre sur seuil 300-400k€
  if (reviews >= 200) score += 70;
  else if (reviews >= 100) score += 60;
  else if (reviews >= 50) score += 50;
  else if (reviews >= 20) score += 35;
  else if (reviews >= 10) score += 20;
  else score += 5;

  // Qualite / serieux perçu (0-20 pts)
  if (rating >= 4.5) score += 20;
  else if (rating >= 4) score += 12;
  else if (rating >= 3.5) score += 5;

  // Presence d'un site web (0-10 pts) — necessaire pour la suite du process (pas de scraping d'obsolescence pour l'instant, critere assoupli)
  if (hasWebsite) score += 10;

  return Math.round(score);
}

const items = $input.all();
const out = [];
for (const item of items) {
  const p = item.json;
  const score = scoreCompany(p);
  if (score < 60) continue;
  if (!p.website) continue; // critere obligatoire: un site doit exister sur le profil/l'entreprise

  // CRITERE OBLIGATOIRE EXPLICITE : CA annuel estime >= 200k euros (proxy = volume d'avis Google).
  // En dessous de ce seuil, l'entreprise est trop petite/recente pour l'offre (souvent une activite
  // solo/tres jeune) -> exclusion, meme si le score pondere depasse 60.
  const reviewsForCA = p.reviewsCount || 0;
  const CA_MINIMUM_ANNUEL_ATTEINT = reviewsForCA >= 20;
  if (!CA_MINIMUM_ANNUEL_ATTEINT) continue;
  out.push({
    json: {
      companyName: p.title || '',
      website: p.website || '',
      address: p.address || '',
      city: p.city || '',
      category: p.categoryName || p.category || '',
      reviewsCount: p.reviewsCount || 0,
      rating: p.totalScore || 0,
      score,
      targetAccountName: p.targetAccountName,
      targetAccountId: p.targetAccountId
    }
  });
}
return out;

const items = $input.all();
const byAccount = {};
for (const item of items) {
  const acc = item.json.targetAccountId;
  if (!byAccount[acc]) byAccount[acc] = [];
  byAccount[acc].push(item.json);
}

const parisNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris' }));
const endOfWindow = new Date(parisNow);
endOfWindow.setHours(19, 0, 0, 0);
const msRemaining = Math.max(endOfWindow.getTime() - parisNow.getTime(), 0);
const runStartMs = Date.now();

const result = [];
for (const acc of Object.keys(byAccount)) {
  const sorted = byAccount[acc].sort((a, b) => (b.score || 0) - (a.score || 0));
  const picked = sorted.slice(0, 16);

  // Etalement dynamique par compte (chaque compte a sa propre cadence sur 8h02-19h00 Paris),
  // avec jitter +/-20% pour eviter un pattern parfaitement regulier.
  const n = Math.max(picked.length, 1);
  const baseIntervalMs = msRemaining / n;
  let cursorMs = 0;
  for (let idx = 0; idx < picked.length; idx++) {
    const jitterFactor = 0.8 + Math.random() * 0.4;
    cursorMs += baseIntervalMs * jitterFactor;
    picked[idx]._waitSeconds = Math.min(Math.max(Math.round(cursorMs / 1000), 20), 39600);
    picked[idx]._runStartMs = runStartMs;
  }
  result.push(...picked);
}
return result.map(j => ({ json: j }));

const parisHour = parseInt(new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: 'numeric', hour12: false }).format(new Date()), 10);
if (parisHour < 8 || parisHour >= 19) {
  return [];
}
return [{ json: $input.item.json }];

